DROP TABLE IF EXISTS `chat_messages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `chat_messages` (
  `case_number` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '案件编号',
  `case_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '案件名称',
  `message_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息唯一ID（案件+文件哈希+行号）',
  `wechat_id` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '微信号',
  `sent_at` datetime DEFAULT NULL COMMENT '发送时间',
  `group_id` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '群ID',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '聊天内容',
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'IP登录地址',
  `embedding` json DEFAULT NULL COMMENT 'BGE-M3 向量，1024 维 float 数组',
  `source_file` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源文件名（可选）',
  `source_row` int DEFAULT NULL COMMENT 'Excel 行号（可选）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`case_number`,`message_id`),
  KEY `idx_chat_case_name` (`case_name`),
  KEY `idx_chat_wechat` (`wechat_id`),
  KEY `idx_chat_group` (`group_id`),
  KEY `idx_chat_sent_at` (`sent_at`),
  KEY `idx_chat_wechat_group` (`wechat_id`,`group_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='群聊消息';
