DROP TABLE IF EXISTS `person_relations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `person_relations` (
  `case_number` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '案件编号',
  `case_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '案件名称',
  `id` bigint NOT NULL AUTO_INCREMENT,
  `person_id_card` varchar(18) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主体人员身份证号',
  `related_id_card` varchar(18) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关系人身份证号',
  `relation_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关系类型，如：父亲、母亲、配偶、同事',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '补充说明，如：该人的父亲',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_person_relation` (`case_number`,`person_id_card`,`related_id_card`,`relation_type`),
  KEY `fk_rel_related` (`case_number`,`related_id_card`),
  KEY `idx_rel_case` (`case_number`),
  KEY `idx_rel_person` (`person_id_card`),
  KEY `idx_rel_related` (`related_id_card`),
  CONSTRAINT `fk_rel_person` FOREIGN KEY (`case_number`, `person_id_card`) REFERENCES `persons` (`case_number`, `id_card`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_rel_related` FOREIGN KEY (`case_number`, `related_id_card`) REFERENCES `persons` (`case_number`, `id_card`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='人员关系';
